//! NautiBurn sidecar client (Brief 5).
//!
//! nauti-inferer stays the thing that answers a request. This module only
//! *talks to* the predictor beside it:
//!   - after a job finishes, POST the scrape so the histogram learns
//!   - before the next job, POST /route to get the named next experts
//!
//! Every call is best-effort. If the engine is down the job must still run, so
//! failures are logged and swallowed rather than propagated. A sidecar that can
//! take the executor down is not a sidecar.

use serde::{Deserialize, Serialize};
use std::time::Duration;
use tracing::{debug, warn};

/// Default bind of `nautiburn-engine serve`. Override with
/// `NAUTIBURN_ENGINE_URL`.
pub const DEFAULT_ENGINE_URL: &str = "http://127.0.0.1:9119";

pub fn engine_url() -> String {
    std::env::var("NAUTIBURN_ENGINE_URL").unwrap_or_else(|_| DEFAULT_ENGINE_URL.to_string())
}

/// True when the operator has not disabled the sidecar. Absent config means on,
/// because a predictor that silently never runs is worse than one that does.
pub fn enabled() -> bool {
    match std::env::var("NAUTIBURN_SIDECAR") {
        Ok(v) => !matches!(v.trim(), "0" | "off" | "false" | "no"),
        Err(_) => true,
    }
}

/// Mirrors `nautiburn_engine::ExpertPass`. Kept as its own type on purpose: the
/// engine is a separate crate reached over HTTP, and a schema bump there must
/// not be a compile error here — it should be a runtime 400 we can log.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExpertPass {
    pub job_id: String,
    pub task_class: String,
    pub phase: String,
    pub layer: u16,
    pub token_index: u32,
    pub token_id: u32,
    pub expert_ids: Vec<u16>,
    pub context_tokens: usize,
}

/// Only the fields the caller needs; the engine returns more.
#[derive(Debug, Clone, Deserialize)]
pub struct NextExperts {
    pub job_id: String,
    pub expert_ids: Vec<u16>,
    pub from_layer: u16,
    pub to_layer: u16,
    pub device: String,
    pub copy_ms_estimate: f64,
    pub within_13ms: bool,
    #[serde(default)]
    pub source: String,
}

#[derive(Clone)]
pub struct Sidecar {
    client: reqwest::Client,
    base: String,
}

impl Sidecar {
    pub fn new() -> Self {
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(3))
            .build()
            .unwrap_or_else(|_| reqwest::Client::new());
        Self {
            client,
            base: engine_url(),
        }
    }

    /// Cheap liveness probe. Used at startup so an unreachable engine is visible
    /// in the log before the first job rather than during it.
    pub async fn health(&self) -> bool {
        match self
            .client
            .get(format!("{}/health", self.base))
            .timeout(Duration::from_millis(1500))
            .send()
            .await
        {
            Ok(r) => r.status().is_success(),
            Err(e) => {
                warn!(error = %e, url = %self.base, "nautiburn engine unreachable");
                false
            }
        }
    }

    /// Named next experts for this job, or `None` if the engine cannot answer.
    pub async fn route(&self, pass: &ExpertPass) -> Option<NextExperts> {
        let url = format!("{}/route", self.base);
        match self.client.post(&url).json(pass).send().await {
            Ok(r) if r.status().is_success() => match r.json::<NextExperts>().await {
                Ok(n) => {
                    debug!(
                        job_id = %pass.job_id,
                        layer = pass.layer,
                        experts = n.expert_ids.len(),
                        within_13ms = n.within_13ms,
                        "nautiburn route"
                    );
                    Some(n)
                }
                Err(e) => {
                    warn!(error = %e, "nautiburn /route decode failed");
                    None
                }
            },
            Ok(r) => {
                warn!(status = %r.status(), job_id = %pass.job_id, "nautiburn /route rejected");
                None
            }
            Err(e) => {
                warn!(error = %e, "nautiburn /route transport failed");
                None
            }
        }
    }

    /// Hand a scrape to the engine. `out` is the path the engine writes; the
    /// engine owns the file, this sidecar only forwards the bytes.
    pub async fn scrape(&self, out: &str, doc: &serde_json::Value) -> bool {
        let url = format!("{}/scrape", self.base);
        let mut body = doc.clone();
        if let Some(obj) = body.as_object_mut() {
            obj.insert("out".to_string(), serde_json::Value::String(out.to_string()));
        }
        match self.client.post(&url).json(&body).send().await {
            Ok(r) if r.status().is_success() => true,
            Ok(r) => {
                warn!(status = %r.status(), "nautiburn /scrape rejected");
                false
            }
            Err(e) => {
                warn!(error = %e, "nautiburn /scrape transport failed");
                false
            }
        }
    }
}

impl Default for Sidecar {
    fn default() -> Self {
        Self::new()
    }
}


