//! Execute inference jobs against fleet llama endpoints.

use crate::adapter::llama;
use crate::jobs::{JobRecord, JobStore};
use crate::scheduler::Scheduler;
use crate::types::Result;
use std::sync::Arc;
use tracing::{error, info};

pub fn spawn_job(
    client: reqwest::Client,
    jobs: Arc<JobStore>,
    job_id: String,
    record: Arc<JobRecord>,
    scheduler: Arc<Scheduler>,
) {
    tokio::spawn(async move {
        let cancelled = record.cancelled.clone();
        let tx = record.tx.clone();
        let url = record.inference_url.clone();
        let model = record.model.clone();
        let messages = record.messages.clone();
        let api_key = record.api_key.clone();
        let reserved_tokens = record.reserved_tokens;
        let mut used_estimate: u64 = 0;

        info!(job_id = %job_id, url = %url, model = %model, "job start");

        // Brief 5 sidecar, step 1: ask the predictor which experts this job will
        // want before the first token is produced. Best-effort — a dead engine
        // must not stop the job.
        if crate::nautiburn_sidecar::enabled() {
            let sidecar = crate::nautiburn_sidecar::Sidecar::new();
            let pass = crate::nautiburn_sidecar::ExpertPass {
                job_id: job_id.clone(),
                // JobRecord has no task_class; the model id is the closest stable
                // discriminator we actually have, and the engine treats it as an
                // opaque class string.
                task_class: model.clone(),
                phase: "decode".to_string(),
                layer: 0,
                token_index: 0,
                token_id: 0,
                expert_ids: Vec::new(),
                context_tokens: 2048,
            };
            if let Some(next) = sidecar.route(&pass).await {
                info!(
                    job_id = %job_id,
                    experts = next.expert_ids.len(),
                    from_layer = next.from_layer,
                    to_layer = next.to_layer,
                    within_13ms = next.within_13ms,
                    source = %next.source,
                    "nautiburn prefetch named"
                );
            }
        }

        let send = |text: String| -> Result<()> {
            // Credit ledger token estimate: very rough chars->tokens heuristic.
            let chars = text.chars().count() as u64;
            let approx = std::cmp::max(1, chars / 4);
            used_estimate = used_estimate.saturating_add(approx);
            let _ = tx.send(text);
            Ok(())
        };

        let result = llama::stream_chat(
            &client,
            &url,
            &model,
            &messages,
            2048,
            0.7,
            cancelled.clone(),
            send,
        )
        .await;

        if let Err(e) = result {
            error!(job_id = %job_id, error = %e, "job failed");
            let _ = tx.send(format!("[error] {e}"));
        }

        // Brief 5 sidecar, step 2: hand the completed request back so the
        // histogram learns. Only the real activation capture is forwarded — when
        // the sidechannel scraper wrote one for this request — so the engine is
        // never fed a synthetic record that would poison the counts.
        if crate::nautiburn_sidecar::enabled() {
            let sidecar = crate::nautiburn_sidecar::Sidecar::new();
            let dir = std::env::var("NAUTIBURN_SCRAPE_DIR")
                .unwrap_or_else(|_| "/tmp/nautiburn-llama-scrape/sidechannel".to_string());
            // Most recent scrape, if any. Best-effort: skip silently when absent.
            let newest = std::fs::read_dir(&dir)
                .ok()
                .and_then(|rd| {
                    rd.filter_map(|e| e.ok())
                        .filter(|e| {
                            let n = e.file_name();
                            let n = n.to_string_lossy();
                            n.starts_with("run-") && !n.contains("-decode")
                        })
                        .max_by_key(|e| e.metadata().ok().and_then(|m| m.modified().ok()))
                })
                .and_then(|e| std::fs::read_to_string(e.path()).ok())
                .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok());
            if let Some(doc) = newest {
                let out = format!("{dir}/job-{job_id}.json");
                sidecar.scrape(&out, &doc).await;
            } else {
                info!(job_id = %job_id, dir = %dir, "no scrape capture for this job; sidecar skipped");
            }
        }

        record.done.store(true, std::sync::atomic::Ordering::Relaxed);

        // Release unused credits (Phase 4).
        if let Some(key) = api_key.as_deref() {
            if reserved_tokens > used_estimate {
                let unused = reserved_tokens - used_estimate;
                let _ = scheduler.release_tokens(key, unused);
            }
        }

        jobs.remove(&job_id);
        info!(job_id = %job_id, "job done");
    });
}


